mapper.select:
select * from (select aaa.* from (







        UNION ALL

        union all



) aaa






)


    order by ${sort} ${direction}

mapper.sql:
select '有效' as effectiveStatusStr, #{VALID_STATUS_01} effectiveStatus, reg.totle_trade_id as busiCode, reg.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, regAdd.EXERCISE_PRICE as exercisePrice, regAdd.redeem_Rate as redeemRate, deal.accountPosition as accountPosition, reg.trade_date as regTradeDate, reg.settle_date as exerciseDate, regAdd.act_sette_date as actExerciseDate, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.ccy as ccy, reg.remark as remark from reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id left join reg_fin_product_deal_total_add regAdd on reg.totle_trade_id=regAdd.totle_trade_id inner join ( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName ,nvl(sum(bb.PTL_BOND_ZHCC),0)/10000 as accountPosition from reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id left join (select a.PORTFOLIO_ID, a.FINPROD_ID,sum(CASE WHEN a.HODING_TYPE =#{A_001} THEN a.AMOUNT ELSE 0 END) AS PTL_BOND_ZHCC from PTL_SEC_POSITION_RULE a where a.cdate = #{cdate,jdbcType=DATE} AND a.DATE_TYPE =#{DATE_TYPE_0} group by a.PORTFOLIO_ID, a.FINPROD_ID )bb on regdeal.finprod_id=bb.FINPROD_ID and regdeal.PORTFOLIO_ID=bb.PORTFOLIO_ID where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON reg.counter_id= mcci.party_id
where 1=1 and reg.trade_status='01' and reg.is_cancel='N'
AND reg.trade_date= #{sysDate,jdbcType=DATE}
AND reg.trade_date>= #{startDate,jdbcType=DATE}
AND reg.trade_date<=#{endDate,jdbcType=DATE}
and (reg.create_user= #{submitUserId} or reg.update_user= #{submitUserId})
AND reg.ps=#{ps}
AND reg.finprod_id in
#{item}
AND reg.sec_manage_acct_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'

select '撤销' as effectiveStatusStr, #{VALID_STATUS_03} effectiveStatus, reg.totle_trade_id as busiCode, reg.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, regAdd.EXERCISE_PRICE as exercisePrice, regAdd.redeem_Rate as redeemRate, deal.accountPosition as accountPosition, reg.trade_date as regTradeDate, reg.settle_date as exerciseDate, regAdd.act_sette_date as actExerciseDate, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.ccy as ccy, reg.remark as remark from reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id left join reg_fin_product_deal_total_add regAdd on reg.totle_trade_id=regAdd.totle_trade_id inner join ( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName ,nvl(sum(bb.PTL_BOND_ZHCC),0)/10000 as accountPosition from reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id left join (select a.PORTFOLIO_ID, a.FINPROD_ID,sum(CASE WHEN a.HODING_TYPE =#{A_001} THEN a.AMOUNT ELSE 0 END) AS PTL_BOND_ZHCC from PTL_SEC_POSITION_RULE a where a.cdate = #{cdate,jdbcType=DATE} AND a.DATE_TYPE =#{DATE_TYPE_0} group by a.PORTFOLIO_ID, a.FINPROD_ID )bb on regdeal.finprod_id=bb.FINPROD_ID and regdeal.PORTFOLIO_ID=bb.PORTFOLIO_ID where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON reg.counter_id= mcci.party_id left join sys_user su on reg.ou_trader_id=su.user_name where 1=1 and reg.trade_status='01' and reg.is_cancel='Y'
AND reg.trade_date= #{sysDate,jdbcType=DATE}
AND reg.trade_date>= #{startDate,jdbcType=DATE}
AND reg.trade_date<=#{endDate,jdbcType=DATE}
and (reg.create_user= #{submitUserId} or reg.update_user= #{submitUserId})
AND reg.ps=#{ps}
AND reg.finprod_id in
#{item}
AND reg.sec_manage_acct_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'

select '流程中' as effectiveStatusStr, #{VALID_STATUS_03} effectiveStatus, reg.totle_trade_id as busiCode, reg.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, regAdd.EXERCISE_PRICE as exercisePrice, regAdd.redeem_Rate as redeemRate, deal.accountPosition as accountPosition, reg.trade_date as regTradeDate, reg.settle_date as exerciseDate, regAdd.act_sette_date as actExerciseDate, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.ccy as ccy, reg.remark as remark from wfl_reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id left join wfl_reg_fin_pro_deal_total_add regAdd on reg.totle_trade_id=regAdd.totle_trade_id inner join ( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName ,nvl(sum(bb.PTL_BOND_ZHCC),0)/10000 as accountPosition from wfl_reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id left join (select a.PORTFOLIO_ID, a.FINPROD_ID,sum(CASE WHEN a.HODING_TYPE =#{A_001} THEN a.AMOUNT ELSE 0 END) AS PTL_BOND_ZHCC from PTL_SEC_POSITION_RULE a where a.cdate = #{cdate,jdbcType=DATE} AND a.DATE_TYPE =#{DATE_TYPE_0} group by a.PORTFOLIO_ID, a.FINPROD_ID )bb on regdeal.finprod_id=bb.FINPROD_ID and regdeal.PORTFOLIO_ID=bb.PORTFOLIO_ID where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON reg.counter_id= mcci.party_id where 1=1
AND reg.trade_date= #{sysDate,jdbcType=DATE}
AND reg.trade_date>= #{startDate,jdbcType=DATE}
AND reg.trade_date<=#{endDate,jdbcType=DATE}
and (reg.create_user= #{submitUserId} or reg.update_user= #{submitUserId})
AND reg.ps=#{ps}
AND reg.finprod_id in
#{item}
AND reg.sec_manage_acct_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'

if.where:
((aaa.effectiveStatusStr || '|' || sdl.ITEM_VALUE || '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr
|| '|' || dictps.ITEM_VALUE || '|' || dicttradeMarket.ITEM_VALUE || '|' || dictsp.ITEM_VALUE
|| '|' || aaa.secManageAcctIdStr || '|' || aaa.busiCode || '|' || aaa.trader
|| '|' || aaa.counterId  || '|' || aaa.counterIdStr || '|' || aaa.portfolioIds  || '|' || aaa.portfolioNames
|| '|' || dictquote.ITEM_VALUE  || '|' || dictms.ITEM_VALUE || '|' || aaa.remark
like '%' || #{search} || '%')
or to_char(aaa.faceValue,'FM9999999999999990.99')=#{search} or to_char(aaa.faceValue)=#{search}
or to_char(aaa.tradeYield,'FM99990.9990')=#{search} or  aaa.tradeYield||'' =#{search}
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.99')=#{search} or to_char(aaa.tradeAmt)=#{search}
or aaa.regTradeDate||'' =#{search}
or aaa.regTradeDate||'' =#{year}||'-'||#{search}
or replace(aaa.regTradeDate,'-','/')||'' =#{search}
or replace(aaa.regTradeDate,'-','/')||'' =#{year}||'/'||#{search}
or aaa.confirmTradeDate||'' =#{search}
or aaa.confirmTradeDate||'' =#{year}||'-'||#{search}
or replace(aaa.confirmTradeDate,'-','/')||'' =#{search}
or replace(aaa.confirmTradeDate,'-','/')||'' =#{year}||'/'||#{search}
)
